contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address attacker, address target) public {
        // The test contract is the deployer of c and therefore has wards[address(this)] == 1.
        // Any address other than address(this), including attacker, should be unauthorized.
        require(attacker != address(this));

        // Read the target ward status before and after the unauthorized call.
        uint256 beforeWard = c.wards(target);

        bool targetReverted;
        try c.deny(target) {
            targetReverted = false;
        } catch {
            targetReverted = true;
        }

        // Since msg.sender is address(this), which is authorized, the call must NOT revert
        // and must set the target's ward to 0.
        assert(!targetReverted && c.wards(target) == 0);
    }

    receive() external payable {}
}

