contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address target) public {
        // Precondition: the caller (this test contract) is authorized as the deployer of c.
        require(c.wards(address(this)) == 1, "caller must be authorized");

        // Before-values read through the public getter.
        uint256 beforeCallerWard = c.wards(address(this));

        // Deciding call: authorized caller denies target. Must not revert.
        bool reverted;
        try c.deny(target) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // After-values read through the public getter.
        uint256 afterTargetWard = c.wards(target);
        uint256 afterCallerWard = c.wards(address(this));

        // General rule: the authorized deny never reverts, clears the target's ward,
        // and does not alter the caller's own ward status.
        assert(!reverted && afterTargetWard == 0 && afterCallerWard == beforeCallerWard);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address target) public {
        // Take a fresh snapshot of the caller's ward status before the deciding call.
        uint256 beforeCallerWard = c.wards(address(this));

        // Deciding call: deny(target). The caller is this test contract.
        bool reverted;
        try c.deny(target) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // After-values read through the public getters.
        uint256 afterTargetWard = c.wards(target);
        uint256 afterCallerWard = c.wards(address(this));

        // General rule: deny reverts exactly when the caller is not authorized (wards[caller] != 1).
        // When authorized (wards[caller] == 1), it never reverts, clears the target's ward to 0,
        // and leaves the caller's ward status unchanged.
        if (beforeCallerWard == 1) {
            assert(!reverted && afterTargetWard == 0 && afterCallerWard == 1);
        } else {
            assert(reverted && afterTargetWard == c.wards(target) && afterCallerWard == beforeCallerWard);
        }
    }

    receive() external payable {}
}

