contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 assets, uint256 shares, address receiver, address owner) public payable {
        require(receiver != owner, "need distinct receiver and owner");

        uint256 supplyBefore = c.totalSupply();
        uint256 receiverBalBefore = c.balanceOf(receiver);
        uint256 ownerBalBefore = c.balanceOf(owner);
        uint256 ownerAllowanceBefore = c.allowance(owner, address(this));

        bool depositReverted;
        try c.deposit(assets, receiver) {
            depositReverted = false;
        } catch {
            depositReverted = true;
        }

        bool withdrawReverted;
        try c.withdraw(assets, receiver, owner) {
            withdrawReverted = false;
        } catch {
            withdrawReverted = true;
        }

        bool redeemReverted;
        try c.redeem(shares, receiver, owner) {
            redeemReverted = false;
        } catch {
            redeemReverted = true;
        }

        uint256 supplyAfter = c.totalSupply();
        uint256 receiverBalAfter = c.balanceOf(receiver);
        uint256 ownerBalAfter = c.balanceOf(owner);
        uint256 ownerAllowanceAfter = c.allowance(owner, address(this));

        assert(
            depositReverted && withdrawReverted && redeemReverted
                && supplyAfter == supplyBefore
                && receiverBalAfter == receiverBalBefore
                && ownerBalAfter == ownerBalBefore
                && ownerAllowanceAfter == ownerAllowanceBefore
        );
    }

    receive() external payable {}
}

