contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 assets, address caller, address receiver) public payable {
        require(assets <= type(uint128).max, "assets too large");
        require(address(this).balance >= 0, "balance check");

        // caller is this test contract, but the transaction's msg.sender for c is this contract.
        // To test the authorization rule, we alternate: the receiver parameter controls whether
        // the caller equals the receiver, which determines revert vs success.
        bool reverted;
        uint256 shares;

        if (caller == receiver) {
            // authorized path: receiver must be this contract
        }

        // decide whether to make an authorized or unauthorized call based on params
        if (caller == address(this)) {
            try c.deposit(assets, receiver) returns (uint256 s) {
                reverted = false;
                shares = s;
            } catch {
                reverted = true;
            }
        } else {
            // call with unauthorized receiver (not msg.sender) must revert
            try c.deposit(assets, receiver) returns (uint256 s) {
                reverted = false;
                shares = s;
            } catch {
                reverted = true;
            }
        }

        // General rule: deposit must revert exactly when msg.sender != receiver.
        // Since msg.sender for c is this contract, the condition is: revert iff receiver != address(this).
        assert((receiver != address(this)) == reverted);
    }

    receive() external payable {}
}

