contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 shares, address receiver, address owner) public {
        require(owner != address(0), "owner is zero");
        require(receiver != address(0), "receiver is zero");

        uint256 maxSharesBefore = c.maxRedeem(owner);
        uint256 previewAssetsBefore = c.previewRedeem(shares);

        require(shares <= maxSharesBefore, "shares exceed maxRedeem");
        require(previewAssetsBefore > 0, "previewRedeem is zero");

        bool reverted;
        uint256 assets;
        try c.redeem(shares, receiver, owner) returns (uint256 assets_) {
            assets = assets_;
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 maxSharesAfter = c.maxRedeem(owner);

        assert(!reverted);
        assert(assets == previewAssetsBefore);
        assert(maxSharesAfter == maxSharesBefore - shares);
    }
}

