contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 assets, address owner, address caller) public payable {
        // If the caller is not the owner, the withApproval modifier must reject it.
        // We cannot impersonate arbitrary msg.sender, but we can still test the
        // rule where the invariant is observed: when msg.sender != owner, call must revert.
        // Because the checker calls run and msg.sender for c is this contract, we test
        // the equivalent condition using the contract's own address as caller.
        bool reverted;
        try c.decreaseDepositRequest(assets, owner) { reverted = false; } catch { reverted = true; }

        // General rule: the call reverts iff the caller is not the owner.
        // Since this test contract's address is the only caller available, the
        // rule reduces to: it reverts unless owner == address(this).
        assert(reverted == (owner != address(this)));
    }

    receive() external payable {}
}

