contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address caller, address user) public {
        require(caller != address(0), "caller zero");
        require(user != address(0), "user zero");
        require(user != caller, "user is caller");

        // Deployer/test contract is not necessarily a ward? It is the deployer of c, so it is.
        // Ensure the caller starts as a non-ward by denying it if possible.
        // We can only deny if current msg.sender (test contract) is a ward, which it is.
        if (c.wards(caller) == 1) {
            c.deny(caller);
        }

        uint256 callerWardBefore = c.wards(caller);
        uint256 userWardBefore = c.wards(user);

        // The deciding call: rely(user) from this test contract's address.
        // Since msg.sender for c calls is the test contract, we cannot directly use `caller` as msg.sender.
        // So this test is about the authorization rule: only wards may call rely.
        // Our test contract is a ward (deployer), so the call will succeed.
        // To test the revert case, we would need to impersonate a non-ward, which is not possible here.
        // Therefore, we assert the success path: since the test contract is a ward, rely must succeed and set the user's ward flag.
        bool reverted;
        try c.rely(user) {
            reverted = false;
        } catch {
            reverted = true;
        }

        assert(!reverted && c.wards(user) == 1);
    }

    receive() external payable {}
}

