contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    event Deposit(address indexed sender, address indexed owner, uint256 assets, uint256 shares);

    function run(uint256 assets, address receiver) public payable {
        // Decide whether deposit should revert based solely on the approval rule:
        // the LP's withApproval(owner) modifier requires msg.sender == owner,
        // where msg.sender is this test contract. Thus deposit must revert
        // iff receiver != address(this).
        bool expectedRevert = (receiver != address(this));

        bool reverted;
        try c.deposit(assets, receiver) returns (uint256 shares) {
            reverted = false;
            // If the call completes without revert, the approval precondition held,
            // and the LP must have emitted Deposit(address(this), receiver, assets, shares).
            // We cannot inspect logs here, so we focus on the revert-vs-complete rule.
            assert(shares >= 0);
        } catch {
            reverted = true;
        }

        // General rule: deposit reverts exactly on the inputs where the caller is
        // not the approved owner (receiver). This must hold for all assets and receivers.
        assert(reverted == expectedRevert);
    }

    receive() external payable {}
}

