    constructor(C _c) { c = _c; }

    function run(address receiver) public payable {
        bool revertedFirst;
        uint256 first;
        try c.maxMint(receiver) returns (uint256 v) {
            first = v;
            revertedFirst = false;
        } catch {
            first = 0;
            revertedFirst = true;
        }

        bool revertedSecond;
        uint256 second;
        try c.maxMint(receiver) returns (uint256 v2) {
            second = v2;
            revertedSecond = false;
        } catch {
            second = 0;
            revertedSecond = true;
        }

        assert(revertedFirst == revertedSecond && (revertedFirst || first == second));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 shares) public {
        // Read the preview: assets required to mint `shares` shares.
        uint256 assets = c.previewMint(shares);

        // The preview must be consistent with the share conversion surface:
        // converting the previewed assets back to shares must return at least
        // the originally requested shares (no free lunch, no impossible mint).
        uint256 convertedShares = c.convertToShares(assets);

        assert(convertedShares >= shares);
    }

    receive() external payable {}
}

