contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address owner, uint256 assets, address receiver) public {
        // Snapshot observable pre-state so the assert uses only read-only calls
        // made before/after the deciding external call.
        uint256 pmBefore = c.previewWithdraw(assets);
        uint256 mwBefore = c.maxWithdraw(owner);

        // Reading public immutable/state getters via the public surface.
        address im = address(c.investmentManager());

        // The rule must hold for all owners, assets, and receivers, but the
        // only sender available to this harness is address(this). We can still
        // force the revert branch by requiring an owner that is not the caller.
        require(owner != address(this), "precondition: caller is not owner");

        bool reverted;
        try c.withdraw(assets, receiver, owner) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // General rule: withdraw must revert when the caller (address(this))
        // is not the owner, regardless of asset/receiver values.
        assert(reverted);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address owner, uint256 assets, address receiver) public {
        // We can only be address(this) as caller; force the unauthorized case by
        // picking an owner different from the harness address.
        owner = address(uint160(uint256(keccak256(abi.encode(owner, assets, receiver)))) | 1);
        if (owner == address(this)) {
            owner = address(uint160(owner) + 1);
        }

        bool reverted;
        try c.withdraw(assets, receiver, owner) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // General rule: withdraw from an owner other than the caller must revert.
        assert(reverted && owner != address(this));
    }

    receive() external payable {}
}

