    constructor(C _c) {
        c = _c;
    }

    function run(uint256 shares) public payable {
        require(true);

        (bool ok1, bytes memory data1) = address(c.investmentManager()).staticcall(
            abi.encodeWithSignature(
                "previewRedeem(address,address,uint256)", address(this), address(c), shares
            )
        );

        (bool ok2, bytes memory data2) = address(c).staticcall(
            abi.encodeWithSignature("previewRedeem(uint256)", shares)
        );

        uint256 expected;
        if (ok1) {
            expected = abi.decode(data1, (uint256));
        }

        uint256 actual;
        if (ok2) {
            actual = abi.decode(data2, (uint256));
        }

        assert(ok1 == ok2 && (ok2 == false || actual == expected));
    }

    receive() external payable {}
}

